def evaluate(
    current_reputation: float,
    observation: dict,
    my_history: list[dict],
    round_num: int
) -> float:
    # Count recent donations from my_history (last 5 entries)
    recent = my_history[-5:] if len(my_history) >= 5 else my_history
    donations = sum(1 for entry in recent if entry["action"] == "donate")
    recent_donation_rate = donations / max(len(recent), 1)

    if observation["action"] == "donate":
        # Reward donation: less reward if already donating frequently
        reward = 0.6 if recent_donation_rate <= 0.5 else 0.3
        new_rep = current_reputation + reward
    else:
        # Punish non-donation: harsher if the agent usually donates
        penalty = -0.1 if recent_donation_rate <= 0.5 else -0.3
        new_rep = current_reputation + penalty
    return max(-1.0, min(1.0, new_rep))

def decide(
    recipient_reputation: float,
    round_num: int,
    my_history: list[dict]
) -> bool:
    # Base threshold: becomes slightly stricter over rounds
    base = min(0.75, 0.35 + round_num * 0.025)

    # Adjust based on our own recent actions
    if my_history:
        last_entry = my_history[-1]
        # If we donated last round, be more generous; if not, be stricter
        if last_entry["action"] == "donate":
            base -= 0.1
        else:
            base += 0.05
        # Also consider partner's action: reciprocate
        if last_entry["partner_action"] == "donate":
            base -= 0.1
        else:
            base += 0.05

    return recipient_reputation > base
